import {forwardRef} from 'react'
import {connect} from 'react-redux'

import type {State} from '../../../../reducers/types'
import {
  getBuild,
  getPipelineBatchIdFromBuildId,
  getPipelineIdFromBuildId,
  getPipelineJobIdFromBuildId,
  getTagsCount,
} from '../../../../selectors'
import type {NormalizedBuild} from '../../../../types'

import Build from './Build'
import type {OwnProps, StateProps} from './Build.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const {
    approvalInfo,
    branchName,
    buildType,
    composite,
    state: buildState,
  }: Partial<NormalizedBuild> = getBuild(state, props.buildId) || {}
  const pipelineId = getPipelineIdFromBuildId(state, props.buildId)
  const jobId = getPipelineJobIdFromBuildId(state, props.buildId)
  const batchId = getPipelineBatchIdFromBuildId(state, props.buildId)
  return {
    state: buildState,
    composite,
    buildTypeId: buildType,
    pipelineId,
    jobId,
    batchId,
    tagsNumber: getTagsCount(state, props.buildId),
    hasBranch: Boolean(branchName),
    approvalStatus: approvalInfo?.status,
  }
}

export default connect(mapStateToProps, null, null, {forwardRef: true})(forwardRef(Build))
