import {useLoadEntityWithAllParents} from '../../../containers/EntityPath'
import withHook from '../../../hocs/withHook'
import {useProjectOrBuildTypeNodeFromUrl, useQueryParams} from '../../../hooks/routes'
import {getFullPath} from '../../../selectors'
import {
  getBatchFilter,
  getBuildTypeFilter,
  getJobFilter,
  getPipelineFilter,
  getProjectBuildTypeFilter,
  toBuildTypeId,
  toProjectId,
} from '../../../types'
import {emptyArray} from '../../../utils/empty'

import BuildPath from './BuildPath'
import type {BuildPathOwnProps, StateProps} from './BuildPath.types'

import {useAppSelector} from 'src/hooks/react-redux'

export default withHook<StateProps, BuildPathOwnProps>(
  ({projectOrBuildTypeNode, leafBuildTypeId, pipelineId, jobId, batchId}) => {
    const filterFromUrl = useProjectOrBuildTypeNodeFromUrl()
    const {buildTypeId: buildTypeIdString, projectId} = useQueryParams()
    const buildTypeId = buildTypeIdString != null ? toBuildTypeId(buildTypeIdString) : undefined
    useLoadEntityWithAllParents({buildTypeId: leafBuildTypeId})
    const path = useAppSelector(state => {
      if (leafBuildTypeId != null && jobId != null && batchId != null) {
        return getFullPath(state, getBatchFilter({id: leafBuildTypeId, jobId, batchId}))
      }
      if (jobId != null) {
        return getFullPath(state, getJobFilter(jobId))
      }
      if (pipelineId != null) {
        return getFullPath(state, getPipelineFilter(pipelineId))
      }
      if (leafBuildTypeId != null) {
        return getFullPath(state, getBuildTypeFilter(leafBuildTypeId))
      }
      return emptyArray
    })

    return {
      projectOrBuildTypeNode:
        projectOrBuildTypeNode ??
        filterFromUrl ??
        getProjectBuildTypeFilter({
          projectId: projectId != null ? toProjectId(projectId) : null,
          buildTypeId,
        }),
      path,
    }
  },
)(BuildPath)
