import classNames from 'classnames'
import type {HTMLAttributes} from 'react'

import {DEFAULT_GRID_ID} from './Grid.consts'

import styles from './Grid.module.css'

type Props = HTMLAttributes<HTMLDivElement> & {
  gridId?: string
}
export default function RowGroupsWrapper({
  className,
  gridId = DEFAULT_GRID_ID,
  ...restProps
}: Props) {
  return (
    <div
      data-grid-id={gridId}
      data-grid-row-groups-wrapper
      className={classNames(styles.rowGroupsWrapper, className)}
      {...restProps}
    />
  )
}
